import numpy as np
from numba import njit, prange


@njit(parallel=True, fastmath=True, cache=True)
def _outer_product(vec1, vec2):
    n = vec1.shape[0]
    m = vec2.shape[0]
    result = np.empty((n, m))
    for i in prange(n):
        vi = vec1[i]
        for j in range(m):
            result[i, j] = vi * vec2[j]
    return result


class Solver:
    def __init__(self):
        # Warm up numba JIT compilation — time doesn't count per problem statement
        a = np.ones(8, dtype=np.float64)
        b = np.ones(8, dtype=np.float64)
        _outer_product(a, b)

    def solve(self, problem):
        vec1, vec2 = problem
        n = len(vec1)
        if n < 64:
            # For small vectors, numpy broadcasting avoids numba call overhead
            return vec1[:, np.newaxis] * vec2
        # For larger vectors, use numba parallel across 4 CPUs
        v1 = np.ascontiguousarray(vec1, dtype=np.float64)
        v2 = np.ascontiguousarray(vec2, dtype=np.float64)
        return _outer_product(v1, v2)

